package com.inventory.skillgapanalysisbackend.controller;
import com.inventory.skillgapanalysisbackend.entity.*; import com.inventory.skillgapanalysisbackend.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController { private final ProjectTaskRepository tasks;private final TaskSubmissionRepository submissions;private final EarningRepository earnings;public TaskController(ProjectTaskRepository t,TaskSubmissionRepository s,EarningRepository e){tasks=t;submissions=s;earnings=e;}
 @GetMapping public List<ProjectTask> all(){return tasks.findAll();} @GetMapping("/open") public List<ProjectTask> open(){return tasks.findByStatus("OPEN");}
 @PostMapping public ResponseEntity<?> create(@RequestBody ProjectTask t){if(t.getTitle()==null||t.getTitle().isBlank())return ResponseEntity.badRequest().body(Map.of("error","Task title is required"));t.setStatus("OPEN");if(t.getRewardAmount()==null||t.getRewardAmount()<0)t.setRewardAmount(0.0);return ResponseEntity.status(201).body(tasks.save(t));}
 @PostMapping("/{taskId}/submit") public ResponseEntity<?> submit(@PathVariable Long taskId,@RequestBody TaskSubmission s){if(!tasks.existsById(taskId))return ResponseEntity.notFound().build();s.setTaskId(taskId);s.setStatus("SUBMITTED");return ResponseEntity.status(201).body(submissions.save(s));}
 @GetMapping("/submissions/student/{userId}") public List<TaskSubmission> submissions(@PathVariable Long userId){return submissions.findByStudentUserId(userId);}
 @PutMapping("/submissions/{submissionId}/approve") public ResponseEntity<?> approve(@PathVariable Long submissionId){Optional<TaskSubmission> so=submissions.findById(submissionId);if(so.isEmpty())return ResponseEntity.notFound().build();TaskSubmission s=so.get();s.setStatus("APPROVED");submissions.save(s);ProjectTask t=tasks.findById(s.getTaskId()).orElse(null);if(t!=null){Earning e=new Earning();e.setStudentUserId(s.getStudentUserId());e.setTaskId(t.getId());e.setAmount(t.getRewardAmount());e.setStatus("PENDING");earnings.save(e);}return ResponseEntity.ok(Map.of("message","Submission approved; earning recorded as pending payout"));}
 @GetMapping("/earnings/{userId}") public ResponseEntity<?> earnings(@PathVariable Long userId){List<Earning> list=earnings.findByStudentUserId(userId);double total=list.stream().filter(e->"PAID".equals(e.getStatus())).mapToDouble(e->e.getAmount()==null?0:e.getAmount()).sum();double pending=list.stream().filter(e->!"PAID".equals(e.getStatus())).mapToDouble(e->e.getAmount()==null?0:e.getAmount()).sum();return ResponseEntity.ok(Map.of("items",list,"paidTotal",total,"pendingTotal",pending));}
}
